64	// ListSessions returns all sessions from the entire/checkpoints/v1 branch,
65	// plus any additional sessions from strategies implementing SessionSource.
66	// It automatically discovers all registered strategies and merges their sessions.
67	func ListSessions(ctx context.Context) ([]Session, error) {
68		repo, err := OpenRepository(ctx)
69		if err != nil {
70			return nil, fmt.Errorf("failed to open git repository: %w", err)
71		}
72		defer repo.Close()
73	
74		// Get checkpoints from the entire/checkpoints/v1 branch
75		checkpoints, err := ListCheckpoints(ctx)
76		if err != nil {
77			return nil, fmt.Errorf("failed to list checkpoints: %w", err)
78		}
79	
80		// Group checkpoints by session ID
81		// For multi-session checkpoints, expand SessionIDs array so each session gets the checkpoint
82		sessionMap := make(map[string]*Session)
83		for _, cp := range checkpoints {
84			// Determine which session IDs this checkpoint belongs to
85			// Multi-session checkpoints have SessionIDs populated; single-session use SessionID
86			sessionIDs := cp.SessionIDs
87			if len(sessionIDs) == 0 {
88				sessionIDs = []string{cp.SessionID}
89			}
90	
91			for _, sessionID := range sessionIDs {
92				if sessionID == "" {
93					continue
94				}
95	
96				if existing, ok := sessionMap[sessionID]; ok {
97					existing.Checkpoints = append(existing.Checkpoints, Checkpoint{
98						CheckpointID:     cp.CheckpointID,
99						Message:          "Checkpoint: " + cp.CheckpointID.String(),
100						Timestamp:        cp.CreatedAt,
101						IsTaskCheckpoint: cp.IsTask,
102						ToolUseID:        cp.ToolUseID,
103					})
104				} else {
105					// Get description from the checkpoint tree
106					description := getDescriptionForCheckpoint(repo, cp.CheckpointID)
107	
108					sessionMap[sessionID] = &Session{
109						ID:          sessionID,
110						Description: description,
111						Strategy:    "", // Will be set from metadata if available
112						StartTime:   cp.CreatedAt,
113						Checkpoints: []Checkpoint{{
114							CheckpointID:     cp.CheckpointID,
115							Message:          "Checkpoint: " + cp.CheckpointID.String(),
116							Timestamp:        cp.CreatedAt,
117							IsTaskCheckpoint: cp.IsTask,
118							ToolUseID:        cp.ToolUseID,
119						}},
120					}
121				}
122			}
123		}
124	
125		// Check for additional sessions
126		strat := NewManualCommitStrategy()
127		if additionalSessions, err := strat.GetAdditionalSessions(ctx); err == nil {
128			for _, addSession := range additionalSessions {
129				if addSession == nil {
130					continue
131				}
132				if existing, ok := sessionMap[addSession.ID]; ok {
133					// Merge checkpoints - deduplicate by CheckpointID
134					existingCPIDs := make(map[string]bool)
135					for _, cp := range existing.Checkpoints {
136						existingCPIDs[cp.CheckpointID.String()] = true
137					}
138					for _, cp := range addSession.Checkpoints {
139						if !existingCPIDs[cp.CheckpointID.String()] {
140							existing.Checkpoints = append(existing.Checkpoints, cp)
141						}
142					}
143					// Update start time if additional session is older
144					if addSession.StartTime.Before(existing.StartTime) {
145						existing.StartTime = addSession.StartTime
146					}
147					// Use description from additional source if existing is empty
148					if existing.Description == "" || existing.Description == NoDescription {
149						existing.Description = addSession.Description
150					}
151				} else {
152					// New session from additional source
153					sessionMap[addSession.ID] = addSession
154				}
155			}
156		}
157	
158		// Convert map to slice
159		sessions := make([]Session, 0, len(sessionMap))
160		for _, session := range sessionMap {
161			// Sort checkpoints within each session by timestamp (most recent first)
162			sort.Slice(session.Checkpoints, func(i, j int) bool {
163				return session.Checkpoints[i].Timestamp.After(session.Checkpoints[j].Timestamp)
164			})
165			sessions = append(sessions, *session)
166		}
167	
168		// Sort sessions by start time (most recent first)
169		sort.Slice(sessions, func(i, j int) bool {
170			return sessions[i].StartTime.After(sessions[j].StartTime)
171		})
172	
173		return sessions, nil
174	}
