176	// GetSession finds a session by ID (supports prefix matching).
177	// Returns ErrNoSession if no matching session is found.
178	func GetSession(ctx context.Context, sessionID string) (*Session, error) {
179		sessions, err := ListSessions(ctx)
180		if err != nil {
181			return nil, err
182		}
183		return findSessionByID(sessions, sessionID)
