186	// getDescriptionForCheckpoint reads the description for a checkpoint from committed checkpoint storage.
187	func getDescriptionForCheckpoint(repo *git.Repository, checkpointID id.CheckpointID) string {
188		tree, err := GetMetadataBranchTree(repo)
189		if err != nil {
190			return NoDescription
191		}
192		description, err := readDescriptionForCheckpointFromTree(tree, checkpointID)
