199	func readDescriptionForCheckpointFromTree(tree *object.Tree, checkpointID id.CheckpointID) (string, error) {
200		// Get the checkpoint tree
201		checkpointTree, err := tree.Tree(checkpointID.Path())
202		if err != nil {
203			return NoDescription, fmt.Errorf("read checkpoint tree: %w", err)
204		}
205	
206		// Read root metadata.json to get session count and sessions map
207		metadataFile, err := checkpointTree.File(paths.MetadataFileName)
208		if err != nil {
209			return NoDescription, fmt.Errorf("read checkpoint metadata: %w", err)
210		}
211	
212		content, err := metadataFile.Contents()
213		if err != nil {
214			return NoDescription, fmt.Errorf("read checkpoint metadata contents: %w", err)
215		}
216	
217		var summary checkpoint.CheckpointSummary
218		if err := json.Unmarshal([]byte(content), &summary); err != nil {
219			return NoDescription, fmt.Errorf("parse checkpoint metadata: %w", err)
220		}
221	
222		// Find the first session's prompt/context path
223		// Try to use the latest session for description (0-based indexing)
224		sessionDir := "0"
225		if len(summary.Sessions) > 0 {
226			sessionDir = strconv.Itoa(len(summary.Sessions) - 1) // Use latest session
227		}
228	
229		sessionTree, err := checkpointTree.Tree(sessionDir)
230		if err != nil {
231			return NoDescription, fmt.Errorf("read checkpoint session tree: %w", err)
