// TestShadowStrategy_GetRewindPoints_V11ReadsPromptFromMirror verifies that
// under checkpoints_version=1.1, the rewind picker reads checkpoint prompt
// text from the topology mirror ref rather than the v1 branch.
//
// Setup makes the mirror the only ref whose tree carries the checkpoint
// metadata: we build a raw commit on v1 whose tree holds both the checkpoint
// summary (needed by listCheckpoints) and prompt.txt at the sharded root path
// (needed by ReadSessionPromptFromTree). We then snapshot v1's tip, re-point
// v1 backward to the initial commit (so v1's tree has no checkpoint
// subdirectory), and point the mirror at the snapshot. listCheckpoints
// (topology-aware) finds the checkpoint via the mirror, so the picker
// proceeds to the metadata tree read. Before the fix the read used v1 (empty
// tree) → empty SessionPrompt; after the fix it uses the mirror's tree →
// wantPrompt.
func TestShadowStrategy_GetRewindPoints_V11ReadsPromptFromMirror(t *testing.T) {
	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	testutil.WriteFile(t, dir, "f.txt", "init")
	testutil.GitAdd(t, dir, "f.txt")
	testutil.GitCommit(t, dir, "init")

	repo, err := git.PlainOpen(dir)
	require.NoError(t, err)

	baseRef, err := repo.Head()
	require.NoError(t, err)
	baseHash := baseRef.Hash()

	cpID := id.MustCheckpointID("a1b2c3d4e5f6")
	const wantPrompt = "only-on-mirror"

	// Build a raw commit on v1 whose tree has two files at the sharded path:
	//
	//   <sharded>/metadata.json  — minimum CheckpointSummary so listCheckpoints
	//                              returns a CheckpointInfo for this id. Only the
	//                              checkpoint_id field is load-bearing here; the
	//                              sessions array is left empty.
	//   <sharded>/prompt.txt     — the prompt content. ReadSessionPromptFromTree
	//                              reads directly from this tree path, not from
	//                              any field in the summary JSON.
	//
	// WriteCommitted writes prompt.txt inside a session subdirectory
	// (<sharded>/0/prompt.txt) rather than at the sharded root, so building the
	// commit directly is the only way to land prompt.txt where the read path
	// looks for it.
	promptBlob, promptErr := checkpoint.CreateBlobFromContent(repo, []byte(wantPrompt))
	require.NoError(t, promptErr)
	summaryJSON := `{"checkpoint_id":"` + cpID.String() + `","sessions":[]}`
	summaryBlob, summaryErr := checkpoint.CreateBlobFromContent(repo, []byte(summaryJSON))
	require.NoError(t, summaryErr)
	shardedPath := cpID.Path() // "a1/b2c3d4e5f6"
	treeEntries := map[string]object.TreeEntry{
		shardedPath + "/prompt.txt": {
			Name: shardedPath + "/prompt.txt",
			Mode: filemode.Regular,
			Hash: promptBlob,
		},
		shardedPath + "/metadata.json": {
			Name: shardedPath + "/metadata.json",
			Mode: filemode.Regular,
			Hash: summaryBlob,
		},
	}
	treeHash, treeErr := checkpoint.BuildTreeFromEntries(t.Context(), repo, treeEntries)
	require.NoError(t, treeErr)
	commitHash, commitErr := checkpoint.CreateCommit(t.Context(), repo, treeHash, plumbing.ZeroHash, "checkpoint commit", "Test", "test@test.com")
	require.NoError(t, commitErr)

	// Point v1 at the new commit, then snapshot it.
	v1Ref := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
	require.NoError(t, repo.Storer.SetReference(plumbing.NewHashReference(v1Ref, commitHash)))

	// Re-point v1 backward to the initial commit so v1's tree has no
	// checkpoint metadata — simulating v1 being ahead of the mirror write.
	require.NoError(t, repo.Storer.SetReference(plumbing.NewHashReference(v1Ref, baseHash)))

